--
-- Estructura de tabla para la tabla `control_manual`
--

CREATE TABLE `control_manual` (
  `id_control` int(11) UNSIGNED NOT NULL,
  `id_dispositivo` int(11) UNSIGNED NOT NULL,
  `foco_numero` int(1) NOT NULL COMMENT '1 = Foco No Esencial, 2 = Foco Esencial',
  `estado_manual` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'true = encendido manualmente, false = apagado manualmente',
  `modo_manual` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'true = modo manual activo, false = modo automático',
  `restablecer_automatico` tinyint(1) DEFAULT 0 COMMENT '1 = restablecer automáticamente, 0 = no restablecer',
  `fecha_restablecimiento` datetime DEFAULT NULL COMMENT 'Fecha y hora programada para restablecer',
  `restablecido` tinyint(1) DEFAULT 0 COMMENT '1 = ya fue restablecido, 0 = pendiente',
  `fecha_control` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

